def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    if not all(isinstance(field, tuple) and len(field) == 3 for field in fields):
        raise ValueError("All fields must be a tuple of (name, type, srid)")

    class PointSubclass(Point):
        _fields = fields
        _srid_map = srid_map

    for field in fields:
        PointSubclass.add_property(field[0], field[1], field[2])

    return PointSubclass

