def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    while True:
        base_set = set()
        for cls in classes:
            base_set.update(cls.__bases__)
        if not base_set:
            break
        classes = list(base_set)
    return classes

