def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        indent += 2  # Increase indent for debug mode
    pretty_str = f"{' ' * indent}{{"
    for key, value in self.__dict__.items():
        pretty_str += f"\n{' ' * (indent + 4)}{key}: "
        if isinstance(value, dict):
            pretty_str += f"{{{', '.join(f'{k}: {v}' for k, v in value.items())}}}"
        else:
            pretty_str += str(value)
        pretty_str += ","
    pretty_str += f"\n{' ' * indent}}}"
    return pretty_str

