        rendered_content = '<div>'
        for piece in pieces:
            rendered_content += f'<p>{piece}</p>'
        rendered_content += '</div>'
    elif style == 'json':
        import json
        rendered_content = json.dumps(pieces)
    elif style == 'text':
        rendered_content = '\n'.join(pieces)

    return rendered_content

