def string_to_int(s, alphabet):
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    try:
        inverse_alphabet = {char: idx for idx, char in enumerate(alphabet)}
    except TypeError:
        raise ValueError("alphabet must be a list of strings") from None

    base = len(alphabet)
    n = 0
    exp = 0
    for char in reversed(s):
        try:
            digit = inverse_alphabet[char]
        except KeyError:
            raise ValueError(f"Character '{char}' not found in alphabet") from None
        n += digit * (base ** exp)
        exp += 1

    return n

