def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc

    for base in bases:
        if hasattr(base,('__metaclass__',)):
            return getattr(base, '__metaclass__')

    global_meta = __metaclass__ if '__metaclass__' in globals() else None
    if global_meta is not None and not bases:
        return global_meta

    return type

