def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        if "links" in data:
            return data
    except json.JSONDecodeError:
        pass

    try:
        from lxml import etree
        root = etree.fromstring(document)
        return {link.attrib['rel']: link.attrib['href'] for link in root.findall(".//link[@rel]")}
    except etree.XMLSyntaxError as e:
        logger.warning("parse_diaspora_webfinger: invalid XML document: %s", e)
        return None

    logger.warning("parse_diaspora_webfinger: unknown document format: %s", document[:100])
    return None

