    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Dictionary to hold the conversion logic for different parsers
    conversion_logics = {
        'main': {
            'arg1': int,
            'arg2': bool,
            'arg3': float
        },
        'virsh': {
            'arg1': int,
            'arg2': str.upper
        },
        'ospd': {
            'arg1': bool
        }
    }

    # Get the conversion logic for the given parser
    conversion_logic = conversion_logics.get(parser_name, {})

    # Apply the conversion logic to the values_dict
    for arg, convert in conversion_logic.items():
        if arg in values_dict:
            try:
                values_dict[arg] = convert(values_dict[arg])
            except (ValueError, TypeError) as e:
                print(f"Error converting {arg}: {e}")
                # Handle the exception as required, e.g., by setting a default value
                values_dict[arg] = None

    return values_dict

